#[test]
fn parity_pack_roundtrip_empty() {
    for rec in load_scenarios("pack_bits.json") {
        if rec["scenario"] == "pack_roundtrip_empty" {
            let scenario = rec["scenario"].as_str().unwrap();
            let factor = flat_i8(&rec["inputs"]["factor"]);
            let shape = shape_of(&rec["inputs"]["factor"]);
            let (rows, cols) = shape2(&shape);
            let packed =
                core::pack_bits(&factor, rows, cols).unwrap_or_else(|e| panic!("{scenario}: {e}"));
            let expected = flat_u8(&face_rec(&rec, "numpy-reference").unwrap()["packed"]);
            assert_bytes(&packed, &expected, scenario);
            assert!(packed.is_empty() || cols == 0, "{scenario}: empty input");
            if let Some(pyo3) = face_rec(&rec, "pyo3") {
                assert_bytes(
                    &packed,
                    &flat_u8(&pyo3["packed"]),
                    &format!("{scenario}: face parity packed"),
                );
            }
        }
    }
}

#[test]
fn parity_pack_layout_bitorder() {
    for rec in load_scenarios("pack_bits.json") {
        if rec["scenario"] == "pack_layout_bitorder" {
            let factor = flat_i8(&rec["inputs"]["factor"]);
            let (rows, cols) = shape2(&shape_of(&rec["inputs"]["factor"]));
            let packed = core::pack_bits(&factor, rows, cols).expect("pack_bits layout");
            // both the NumPy record and the explicit expected-bytes record
            let numpy_rec = flat_u8(&face_rec(&rec, "numpy-reference").unwrap()["packed"]);
            assert_bytes(&packed, &numpy_rec, "layout vs numpy-reference");
            let expected = flat_u8(&face_rec(&rec, "numpy-reference").unwrap()["expected_bytes"]);
            assert_bytes(&packed, &expected, "layout vs expected bytes");
            // byte j = k//8 with bit k%8 set for the single +1 rows
            for (r, row) in factor.chunks(cols).enumerate() {
                for (k, &v) in row.iter().enumerate() {
                    let bit = (packed[r * 2 + (k / 8)] >> (k % 8)) & 1;
                    assert_eq!(bit, if v == 1 { 1 } else { 0 });
                }
            }
            if let Some(pyo3) = face_rec(&rec, "pyo3") {
                assert_bytes(
                    &packed,
                    &flat_u8(&pyo3["packed"]),
                    "layout: face parity packed",
                );
            }
        }
    }
}

#[test]
fn parity_pack_rejects_non_binary() {
    // off-values raise KernelError (mapped to ValueError on the PyO3 face)
    let bad: Vec<Vec<i8>> = vec![vec![0, 1], vec![1, 2], vec![1, -2]];
    for row in &bad {
        let r = core::pack_bits(row, 1, 2);
        assert!(r.is_err(), "expected error for {row:?}");
    }
    let float_bad: Vec<Vec<f64>> = vec![vec![0.5, 1.0], vec![1.0, 0.0]];
    for row in &float_bad {
        let as_i8: Vec<i8> = row.iter().map(|&v| v as i8).collect();
        // 0.5 truncates to 0 -> reject; 0.0 truncates to 0 -> reject
        let r = core::pack_bits(&as_i8, 1, 2);
        assert!(r.is_err(), "expected error for {row:?}");
    }
}

